head.b:skin:
/* Garak Hansang premium merchant Blogger theme draft. Validate inside actual Blogger account before using. */
:root{--deep:#0d443b;--accent:#13845e;--cream:#f8f7ef;--ink:#1b3b35}
*{box-sizing:border-box}
html,body{margin:0;padding:0;background:var(--cream);color:var(--ink);font-family:'Malgun Gothic','Noto Sans KR',Arial,sans-serif;line-height:1.8}
a{color:var(--accent);text-decoration:none}img{max-width:100%;height:auto}
.yg-top{padding:8px 20px;background:var(--deep);color:#ddf3e6;text-align:center;font-size:12px;font-weight:bold}
.yg-header{background:white;border-bottom:1px solid #e5e9dc;padding:16px 20px}.yg-shell{max-width:1100px;margin:0 auto}
.yg-brand{font-weight:900;color:#124c3e;font-size:27px;letter-spacing:-.06em}.yg-brand small{color:#718d80;font-size:12px;letter-spacing:0}
.yg-links{display:flex;gap:15px;flex-wrap:wrap;margin-top:8px;font-size:12px;font-weight:bold}
.yg-cover{background:linear-gradient(125deg,#0e443c,#123c54);padding:70px 20px 65px;color:#fff}.yg-cover h1{color:#fff;font-size:clamp(34px,5vw,56px);letter-spacing:-.07em;line-height:1.25;margin:0 0 13px}
.yg-cover p{color:#c8e5da;margin:0 0 24px}.yg-cover a{display:inline-block;border-radius:11px;background:#a5ebc9;color:#073f36;padding:11px 20px;font-weight:900;font-size:12px}
.yg-content{padding:50px 20px 80px;display:grid;grid-template-columns:minmax(0,1fr) 285px;gap:35px}
.yg-main{min-width:0}
.yg-sidebar{background:#fff;border:1px solid #e0e9db;border-radius:17px;padding:24px;height:max-content;position:sticky;top:20px}
.yg-sidebar h3{margin:0 0 10px;color:var(--deep);font-size:18px}
.yg-sidebar p{font-size:12px;color:#6c8175}
.yg-button{display:block;background:#117954;color:white;font-size:12px;font-weight:900;padding:11px 14px;border-radius:9px;text-align:center;margin:8px 0}
.post-outer,.post{background:#fff;border:1px solid #e1e9e2;border-radius:17px;padding:25px;margin-bottom:22px}
.post-title,.entry-title{font-size:clamp(24px,3vw,36px);letter-spacing:-.055em;line-height:1.35}
.post-body{font-size:15px;line-height:1.9;overflow-wrap:anywhere}
.blog-pager a{display:inline-block;margin:10px}
.yg-footer{background:#082d25;color:#d3e4d7;padding:28px 20px;font-size:12px}
@media(max-width:810px){.yg-content{grid-template-columns:1fr}.yg-sidebar{position:static}.yg-cover{padding:48px 18px}.post-outer,.post{padding:16px}.yg-brand{font-size:23px}}
